package com.example.orchestrator; import java.util.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestTemplate; @RestController @RequestMapping("/api/saga") public class SagaController { private final RestTemplate rt=new RestTemplate(); @PostMapping("/checkout") public Map<String,Object> checkout(@RequestBody Map<String,Object> r){Map<?,?> o=rt.postForObject("http://order-service:8081/api/orders",r,Map.class); String id=(String)o.get("orderId"); boolean inv=false,pay=false; try{rt.postForObject("http://inventory-service:8083/api/inventory/reserve",r,Map.class);inv=true;rt.postForObject("http://payment-service:8082/api/payments/authorize",r,Map.class);pay=true;rt.postForObject("http://order-service:8081/api/orders/"+id+"/complete",null,Map.class);return Map.of("orderId",id,"status","COMPLETED");}catch(Exception e){if(inv)try{rt.postForObject("http://inventory-service:8083/api/inventory/release",null,Map.class);}catch(Exception ignored){}if(pay)try{rt.postForObject("http://payment-service:8082/api/payments/refund",null,Map.class);}catch(Exception ignored){}try{rt.postForObject("http://order-service:8081/api/orders/"+id+"/cancel",null,Map.class);}catch(Exception ignored){}return Map.of("orderId",id,"status","COMPENSATED","reason",String.valueOf(e.getMessage()));}}}
